{
  "name": "@neuralnomads/opencode-gaffer",
  "version": "0.3.0",
  "description": "OpenCode for Gaffer: bounded graph editing through an authenticated local host, with an optional in-app conversation panel.",
  "license": "MIT",
  "type": "module",
  "keywords": [
    "opencode-integration",
    "opencode",
    "gaffer"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/NeuralNomadsAI/opencode-integrations",
    "directory": "integrations/gaffer/plugin"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "methods",
    "programs",
    "host",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "node scripts/build.ts",
    "build:host": "node scripts/build-host.ts",
    "typecheck": "tsc -p tsconfig.json"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.2.0 || ^0.0.0-dev"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.5",
    "@opencode/client": "2.2.5",
    "esbuild": "0.28.2"
  },
  "opencodeIntegration": {
    "spec": 0,
    "id": "gaffer",
    "displayName": "OpenCode for Gaffer",
    "family": "native",
    "plugin": "neuralnomads.gaffer",
    "rpc": "neuralnomads.gaffer",
    "host": {
      "app": "gaffer",
      "protocol": 1,
      "range": "^0.3.0",
      "appVersions": ">=1.6",
      "payload": "host/gaffer/opencode_link-0.3.0.zip",
      "sha256": "0ad49be2c312d3a1b8fc2980980707cd717c56ad060aaf0bbb98703141d24e5b"
    }
  }
}
